import React, { useState, useEffect, useCallback } from 'react';
import { Card, Button, Input, Alert, api } from '../App';

const Label = ({ children, style }) => (
  <div style={{ fontSize: 11, fontWeight: 700, color: '#444', textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 8, ...style }}>{children}</div>
);

export default function MappingPage() {
  const [parties,      setParties]      = useState([]);
  const [allGardens,   setAllGardens]   = useState([]);
  const [allGrades,    setAllGrades]    = useState([]);
  const [allBrokers,   setAllBrokers]   = useState([]);
  const [gradeGardens, setGradeGardens] = useState({});

  const [selected,     setSelected]     = useState(null);
  const [search,       setSearch]       = useState('');
  const [saving,       setSaving]       = useState(false);
  const [alert,        setAlert]        = useState(null);
  const [addMode,      setAddMode]      = useState(false);
  const [newParty,     setNewParty]     = useState({ name: '', code: '' });
  const [importing,    setImporting]    = useState(false);
  const [importResult, setImportResult] = useState(null);
  const [gSearch,      setGSearch]      = useState('');

  // Party master state
  const [selectedGrades, setSelectedGrades] = useState([]);
  const [mappedGardens,  setMappedGardens]  = useState([]);
  const [brokerList,     setBrokerList]     = useState([]);
  // Per-grade settings: { BOP: { maxLots, rateMin, rateMax, bagsFrom, bagsTo, nwtFrom, nwtTo } }
  const [gradeSettings,  setGradeSettings]  = useState({});

  const load = useCallback(async () => {
    const [p, g, gr, br] = await Promise.all([
      api.get('/mapping/summary/all').catch(() => ({ data: [] })),
      api.get('/mapping/gardens').catch(() => ({ data: [] })),
      api.get('/marking/grades/list').catch(() => ({ data: [] })),
      api.get('/mapping/brokers-available').catch(() => ({ data: [] }))
    ]);
    setParties(p.data);
    setAllGardens(g.data);
    setAllGrades(gr.data);
    setAllBrokers(br.data);
  }, []);

  const loadGradeGardens = useCallback(async () => {
    try { const r = await api.get('/mapping/grade-gardens'); setGradeGardens(r.data || {}); }
    catch (e) {}
  }, []);

  useEffect(() => { load(); loadGradeGardens(); }, [load, loadGradeGardens]);

  const selectParty = async (p) => {
    setSelected(p); setAlert(null);
    try {
      const r = await api.get(`/mapping/party-master/${p.id}`);
      const pm = r.data;
      setMappedGardens(pm.gardens || []);
      setBrokerList(pm.broker_list || []);

      // Reconstruct gradeSettings from stored data
      const gs = pm.grade_samples || {};
      const gr = pm.grade_ranges  || {};
      const bf = pm.bags_from || 0;
      const bt = pm.bags_to   || 0;
      const nf = pm.nwt_from  || 0;
      const nt = pm.nwt_to    || 0;

      const combined = {};
      const usedGrades = Object.keys(gs).filter(g => gs[g] > 0);
      usedGrades.forEach(g => {
        combined[g] = {
          maxLots:  gs[g] || 0,
          rateMin:  gr[g]?.min || 0,
          rateMax:  gr[g]?.max || 0,
          bagsFrom: bf,
          bagsTo:   bt,
          nwtFrom:  nf,
          nwtTo:    nt
        };
      });
      setGradeSettings(combined);
      setSelectedGrades(usedGrades);
    } catch (e) {
      setMappedGardens([]); setBrokerList([]); setGradeSettings({}); setSelectedGrades([]);
    }
  };

  const toggleGrade = (grade) => {
    const isNowSelected = !selectedGrades.includes(grade);
    const newSel = isNowSelected
      ? [...selectedGrades, grade]
      : selectedGrades.filter(g => g !== grade);
    setSelectedGrades(newSel);

    if (isNowSelected) {
      // Add default grade settings
      setGradeSettings(prev => ({
        ...prev,
        [grade]: { maxLots: 0, rateMin: 0, rateMax: 0, bagsFrom: 0, bagsTo: 0, nwtFrom: 0, nwtTo: 0 }
      }));
      // Auto-add gardens for this grade
      const gardensList = gradeGardens[grade] || [];
      setMappedGardens(prev => Array.from(new Set([...prev, ...gardensList])));
    } else {
      // Remove grade settings
      setGradeSettings(prev => { const n = { ...prev }; delete n[grade]; return n; });
      // Remove gardens only in deselected grade (not in any other selected grade)
      const remaining = newSel;
      const keepGardens = new Set();
      remaining.forEach(g => (gradeGardens[g] || []).forEach(garden => keepGardens.add(garden)));
      setMappedGardens(prev => prev.filter(g => keepGardens.has(g)));
    }
  };

  const setGS = (grade, field, val) => {
    setGradeSettings(prev => ({
      ...prev,
      [grade]: { ...(prev[grade] || {}), [field]: val === '' ? 0 : parseFloat(val) || 0 }
    }));
  };

  const toggleGarden = (g) => setMappedGardens(m => m.includes(g) ? m.filter(x => x !== g) : [...m, g]);
  const toggleBroker = (b) => setBrokerList(l => l.includes(b) ? l.filter(x => x !== b) : [...l, b]);

  const saveAll = async () => {
    if (!selected) return;
    setSaving(true);

    // Build grade_samples, grade_ranges from gradeSettings
    const grade_samples = {};
    const grade_ranges  = {};
    // bags/nwt — use values from first grade that has them (they're global)
    let bags_from = 0, bags_to = 0, nwt_from = 0, nwt_to = 0;

    selectedGrades.forEach(g => {
      const s = gradeSettings[g] || {};
      grade_samples[g] = s.maxLots || 0;
      grade_ranges[g]  = { min: s.rateMin || 0, max: s.rateMax || 0 };
      // Use first non-zero value for global filters
      if (s.bagsFrom) bags_from = s.bagsFrom;
      if (s.bagsTo)   bags_to   = s.bagsTo;
      if (s.nwtFrom)  nwt_from  = s.nwtFrom;
      if (s.nwtTo)    nwt_to    = s.nwtTo;
    });

    try {
      await api.post('/mapping', {
        party_id: selected.id,
        gardens:  mappedGardens,
        grade_samples, grade_ranges,
        broker_list: brokerList,
        bags_from, bags_to, nwt_from, nwt_to,
        skip_blank_lsp: false,
        skip_dup_broker_garden_grade: false
      });
      setAlert({ msg: `✅ Party Master saved for ${selected.party_name}`, type: 'success' });
      load();
    } catch (e) {
      setAlert({ msg: '❌ ' + (e.response?.data?.error || e.message), type: 'error' });
    } finally { setSaving(false); }
  };

  const addParty = async () => {
    if (!newParty.name || !newParty.code) { setAlert({ msg: 'Name and code required', type: 'error' }); return; }
    try {
      await api.post('/parties', { party_name: newParty.name, party_code: newParty.code });
      setNewParty({ name: '', code: '' }); setAddMode(false); load();
    } catch (e) { setAlert({ msg: e.response?.data?.error || e.message, type: 'error' }); }
  };

  const delParty = async (id, name) => {
    if (!window.confirm(`Delete "${name}"?`)) return;
    await api.delete(`/parties/${id}`);
    setSelected(null); load();
  };

  const importParties = async (file) => {
    setImporting(true); setImportResult(null);
    const fd = new FormData(); fd.append('file', file);
    try { const r = await api.post('/mapping/import-parties', fd); setImportResult(r.data); load(); }
    catch (e) { setImportResult({ error: e.response?.data?.error || e.message }); }
    finally { setImporting(false); }
  };

  const filteredParties = parties.filter(p =>
    p.party_name.toLowerCase().includes(search.toLowerCase()) ||
    p.party_code.toLowerCase().includes(search.toLowerCase())
  );

  const gardensInSelectedGrades = selectedGrades.length > 0
    ? [...new Set(selectedGrades.flatMap(g => gradeGardens[g] || []))]
    : allGardens;
  const filteredGardens = gardensInSelectedGrades.filter(g =>
    g.toLowerCase().includes(gSearch.toLowerCase())
  );

  const chip = (sel, selBg, selBorder, selText) => ({
    padding: '4px 12px', borderRadius: 20, cursor: 'pointer', fontSize: 12, fontWeight: 600,
    border: `1.5px solid ${sel ? selBorder : '#e2e8f0'}`,
    background: sel ? selBg : '#f9fafb', color: sel ? selText : '#666',
    userSelect: 'none', transition: 'all 0.1s'
  });

  const numIn = (val, onChange, w = 70) => (
    <input type="number" value={val || ''} onChange={e => onChange(e.target.value)} placeholder="0"
      style={{ width: w, padding: '5px 8px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
  );

  return (
    <div>
      <h2 style={{ marginBottom: 4, color: '#1a3c5e' }}>🔗 Party Master</h2>
      <p style={{ color: '#888', fontSize: 13, marginBottom: 16 }}>Configure grades, brokers, gardens and lot filters per party.</p>
      {alert && <Alert msg={alert.msg} type={alert.type} />}

      <div style={{ display: 'flex', gap: 16, alignItems: 'flex-start' }}>
        {/* ── LEFT: Party list ── */}
        <Card style={{ width: 240, minWidth: 220, flexShrink: 0, padding: 12 }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 }}>
            <h3 style={{ fontSize: 13 }}>Parties ({filteredParties.length})</h3>
            <div style={{ display: 'flex', gap: 4 }}>
              <Button size="sm" variant="outline" onClick={() => document.getElementById('pimport').click()} style={{ fontSize: 10, padding: '3px 7px' }}>
                {importing ? '…' : '📥'}
              </Button>
              <input id="pimport" type="file" accept=".xlsx,.xls" style={{ display: 'none' }}
                onChange={e => { if (e.target.files[0]) importParties(e.target.files[0]); e.target.value = ''; }} />
              <Button size="sm" onClick={() => setAddMode(!addMode)} style={{ fontSize: 11, padding: '3px 8px' }}>+ Add</Button>
            </div>
          </div>

          {importResult && (
            <div style={{ fontSize: 11, padding: '5px 8px', borderRadius: 5, marginBottom: 8, background: importResult.error ? '#fee2e2' : '#f0fdf4', color: importResult.error ? '#991b1b' : '#166534' }}>
              {importResult.error ? `❌ ${importResult.error}` : `✅ ${importResult.imported} imported`}
            </div>
          )}

          {addMode && (
            <div style={{ background: '#f0f8ff', padding: 10, borderRadius: 6, marginBottom: 10 }}>
              <Input label="Name" value={newParty.name} onChange={v => setNewParty(p => ({ ...p, name: v }))} placeholder="ASHA TEA" />
              <Input label="Code" value={newParty.code} onChange={v => setNewParty(p => ({ ...p, code: v.toUpperCase() }))} placeholder="AA" />
              <div style={{ display: 'flex', gap: 6 }}>
                <Button size="sm" variant="success" onClick={addParty}>Save</Button>
                <Button size="sm" variant="outline" onClick={() => setAddMode(false)}>Cancel</Button>
              </div>
            </div>
          )}

          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search…"
            style={{ width: '100%', padding: '6px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 12, marginBottom: 8 }} />

          <div style={{ maxHeight: 600, overflowY: 'auto' }}>
            {filteredParties.length === 0 && (
              <div style={{ color: '#aaa', fontSize: 12, padding: 10, textAlign: 'center' }}>
                {parties.length === 0 ? 'No parties. Import PC.xlsx or + Add.' : 'No match.'}
              </div>
            )}
            {filteredParties.map(p => (
              <div key={p.id} onClick={() => selectParty(p)}
                style={{ padding: '6px 8px', borderRadius: 6, cursor: 'pointer', marginBottom: 2,
                  background: selected?.id === p.id ? '#dbeafe' : '#f9fafb',
                  border: `1.5px solid ${selected?.id === p.id ? '#93c5fd' : 'transparent'}`,
                  display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <span style={{ fontWeight: 700, fontSize: 11, color: '#1a3c5e' }}>[{p.party_code}]</span>
                  <span style={{ fontSize: 11, marginLeft: 4 }}>{p.party_name}</span>
                  <div style={{ fontSize: 10, color: '#888' }}>{p.garden_count || 0} gardens</div>
                </div>
                <button onClick={e => { e.stopPropagation(); delParty(p.id, p.party_name); }}
                  style={{ background: 'none', border: 'none', cursor: 'pointer', color: '#ddd', fontSize: 11 }}>✕</button>
              </div>
            ))}
          </div>
        </Card>

        {/* ── RIGHT: Party Master form ── */}
        {!selected
          ? <Card style={{ flex: 1, textAlign: 'center', padding: 50, color: '#aaa' }}>Select a party to configure their Party Master</Card>
          : (
            <div style={{ flex: 1, display: 'flex', flexDirection: 'column', gap: 14 }}>
              {/* Header */}
              <Card style={{ padding: '12px 18px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                <div>
                  <h3 style={{ fontSize: 16 }}>[{selected.party_code}] {selected.party_name}</h3>
                  <div style={{ fontSize: 12, color: '#888' }}>{mappedGardens.length} gardens · {selectedGrades.length} grades · {brokerList.length > 0 ? brokerList.join(', ') : 'All brokers'}</div>
                </div>
                <Button variant="success" onClick={saveAll} disabled={saving} style={{ padding: '10px 24px' }}>
                  {saving ? 'Saving…' : '💾 Save Party Master'}
                </Button>
              </Card>

              {/* ── SECTION 1: Grades ── */}
              <Card style={{ padding: 16 }}>
                <Label>1. Select Grades — Selecting a grade auto-loads its gardens below</Label>
                <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                  {allGrades.map(g => (
                    <div key={g} onClick={() => toggleGrade(g)}
                      style={chip(selectedGrades.includes(g), '#dcfce7', '#1a7a4a', '#166534')}>
                      {selectedGrades.includes(g) ? '✓ ' : ''}{g}
                    </div>
                  ))}
                </div>
                {selectedGrades.length > 0 && (
                  <div style={{ fontSize: 11, color: '#888', marginTop: 6 }}>Selected: {selectedGrades.join(', ')}</div>
                )}
              </Card>

              {/* ── SECTION 2: Broker + Per-Grade Settings (merged) ── */}
              {selectedGrades.length > 0 && (
                <Card style={{ padding: 16 }}>
                  <Label>2. Brokers &amp; Grade Settings (Max Lots · Rate Range · Bags · Net Wt)</Label>

                  {/* Broker selection */}
                  <div style={{ marginBottom: 14 }}>
                    <div style={{ fontSize: 12, fontWeight: 600, color: '#555', marginBottom: 6 }}>
                      Broker List <span style={{ fontWeight: 400, color: '#aaa' }}>(leave empty = all brokers)</span>
                    </div>
                    <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap' }}>
                      {allBrokers.map(b => (
                        <div key={b} onClick={() => toggleBroker(b)}
                          style={chip(brokerList.includes(b), '#dbeafe', '#1a3c5e', '#1e40af')}>
                          {brokerList.includes(b) ? '✓ ' : ''}{b}
                        </div>
                      ))}
                    </div>
                    {brokerList.length > 0 && (
                      <div style={{ fontSize: 11, color: '#1e40af', marginTop: 5 }}>Selected: {brokerList.join(', ')}</div>
                    )}
                  </div>

                  <div style={{ height: 1, background: '#f0f4f8', margin: '14px 0' }} />

                  {/* Per-grade settings table */}
                  <div style={{ overflowX: 'auto' }}>
                    <table style={{ borderCollapse: 'collapse', fontSize: 12, width: '100%' }}>
                      <thead>
                        <tr style={{ background: '#f0f4f8' }}>
                          <th style={{ padding: '7px 12px', textAlign: 'left', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Grade</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Max Lots</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Rate Min ₹</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Rate Max ₹</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Bags From</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Bags To</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Net Wt From</th>
                          <th style={{ padding: '7px 12px', textAlign: 'center', fontWeight: 700, color: '#444', whiteSpace: 'nowrap' }}>Net Wt To</th>
                        </tr>
                      </thead>
                      <tbody>
                        {selectedGrades.map((g, i) => {
                          const s = gradeSettings[g] || {};
                          return (
                            <tr key={g} style={{ borderBottom: '1px solid #f0f4f8', background: i % 2 === 0 ? '#fff' : '#fafbfc' }}>
                              <td style={{ padding: '8px 12px' }}>
                                <span style={{ background: '#dbeafe', color: '#1e40af', padding: '2px 10px', borderRadius: 99, fontWeight: 700, fontSize: 12 }}>{g}</span>
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.maxLots || ''}
                                  onChange={e => setGS(g, 'maxLots', e.target.value)} placeholder="0"
                                  style={{ width: 65, padding: '5px 6px', border: `1.5px solid ${s.maxLots > 0 ? '#1a7a4a' : '#cbd5e0'}`, borderRadius: 6, fontSize: 12, textAlign: 'center', fontWeight: s.maxLots > 0 ? 700 : 400, color: s.maxLots > 0 ? '#166534' : '#555' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.rateMin || ''}
                                  onChange={e => setGS(g, 'rateMin', e.target.value)} placeholder="0"
                                  style={{ width: 70, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.rateMax || ''}
                                  onChange={e => setGS(g, 'rateMax', e.target.value)} placeholder="0"
                                  style={{ width: 70, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.bagsFrom || ''}
                                  onChange={e => setGS(g, 'bagsFrom', e.target.value)} placeholder="0"
                                  style={{ width: 65, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.bagsTo || ''}
                                  onChange={e => setGS(g, 'bagsTo', e.target.value)} placeholder="0"
                                  style={{ width: 65, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.nwtFrom || ''}
                                  onChange={e => setGS(g, 'nwtFrom', e.target.value)} placeholder="0"
                                  style={{ width: 70, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                              <td style={{ padding: '8px 12px', textAlign: 'center' }}>
                                <input type="number" min="0" value={s.nwtTo || ''}
                                  onChange={e => setGS(g, 'nwtTo', e.target.value)} placeholder="0"
                                  style={{ width: 70, padding: '5px 6px', border: '1.5px solid #cbd5e0', borderRadius: 6, fontSize: 12, textAlign: 'center' }} />
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </Card>
              )}

              {/* ── SECTION 3: Gardens ── */}
              <Card style={{ padding: 16 }}>
                <Label>3. Gardens — {selectedGrades.length > 0 ? `Filtered for: ${selectedGrades.join(', ')}` : 'All gardens (select grades above to filter)'}</Label>
                <div style={{ display: 'flex', gap: 8, marginBottom: 10, alignItems: 'center' }}>
                  <input value={gSearch} onChange={e => setGSearch(e.target.value)} placeholder="Search gardens…"
                    style={{ flex: 1, padding: '7px 10px', border: '1.5px solid #e2e8f0', borderRadius: 6, fontSize: 13 }} />
                  <Button size="sm" variant="outline" onClick={() => setMappedGardens([...filteredGardens])}>Select All</Button>
                  <Button size="sm" variant="outline" onClick={() => setMappedGardens([])}>Clear</Button>
                  <span style={{ fontSize: 12, color: '#888', whiteSpace: 'nowrap' }}>{mappedGardens.length} selected</span>
                </div>
                <div style={{ display: 'flex', gap: 7, flexWrap: 'wrap', maxHeight: 220, overflowY: 'auto' }}>
                  {filteredGardens.length === 0
                    ? <div style={{ color: '#aaa', fontSize: 13 }}>No gardens. Import Catalogue first.</div>
                    : filteredGardens.map(g => (
                      <div key={g} onClick={() => toggleGarden(g)}
                        style={chip(mappedGardens.includes(g), '#dcfce7', '#1a7a4a', '#166534')}>
                        {mappedGardens.includes(g) ? '✓ ' : ''}{g}
                      </div>
                    ))
                  }
                </div>
              </Card>
            </div>
          )
        }
      </div>
    </div>
  );
}
